#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelNonzero {
public:
    __aicore__ inline KernelNonzero() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR out,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                int64_t totalLength, int64_t ndim,
                                GM_ADDR strides, GM_ADDR outOffset)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            this->blockOffset = formerLength * blockIdx;
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            this->blockOffset = formerLength * formerNum + tailLength * tailIdx;
        }

        this->tileLength = tileLength;
        this->totalLength = totalLength;
        this->ndim = ndim;

        xGm.SetGlobalBuffer((__gm__ T *)x, totalLength);
        outGm.SetGlobalBuffer((__gm__ int64_t *)out, totalLength * ndim);
        stridesGm.SetGlobalBuffer((__gm__ int64_t *)strides, ndim);
        outOffsetGm.SetGlobalBuffer((__gm__ int64_t *)outOffset, 1);

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueIdx, BUFFER_NUM, tileLength * sizeof(int64_t));

        if constexpr (sizeof(T) == 2) {
            pipe.InitBuffer(castBuf, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if (this->blockLength <= 0) {
            return;
        }

        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;

        for (int64_t i = 0; i < tileNum; ++i) {
            int64_t curTileLength = this->tileLength;
            if (i == tileNum - 1) {
                curTileLength = this->blockLength - i * this->tileLength;
            }
            if (curTileLength <= 0) {
                break;
            }

            int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
            int64_t alignedTileLen = ((curTileLength + alignNum - 1) / alignNum) * alignNum;

            CopyIn(i, alignedTileLen);
            Compute(i, curTileLength, alignedTileLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        int64_t offset = this->blockOffset + progress * this->tileLength;

        AscendC::DataCopyExtParams copyParams{1,
            static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[offset], copyParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength, int64_t alignedTileLen)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();

        int64_t offset = this->blockOffset + progress * this->tileLength;

        // Get output offset for this core
        int64_t outOffset = outOffsetGm.GetValue(0);

        // Count non-zero elements before this tile within this core
        int64_t preCount = 0;
        for (int64_t j = 0; j < progress; ++j) {
            int64_t checkLen = this->tileLength;
            if (j == (this->blockLength + this->tileLength - 1) / this->tileLength - 1) {
                checkLen = this->blockLength - j * this->tileLength;
            }
            int64_t tileOffset = this->blockOffset + j * this->tileLength;
            for (int64_t k = 0; k < checkLen; ++k) {
                if (!IsZero(xLocal, tileOffset + k - offset)) {
                    preCount++;
                }
            }
        }

        // Process each element in current tile
        for (int64_t k = 0; k < curTileLength; ++k) {
            int64_t globalIdx = offset + k;
            if (!IsZero(xLocal, k)) {
                int64_t outRow = outOffset + preCount;

                // Compute multi-dimensional indices from flat index
                int64_t remain = globalIdx;
                for (int64_t d = 0; d < this->ndim; ++d) {
                    int64_t stride = stridesGm.GetValue(d);
                    int64_t idx = remain / stride;
                    remain = remain % stride;

                    int64_t outPos = outRow * this->ndim + d;
                    outGm.SetValue(outPos, idx);
                }
                preCount++;
            }
        }

        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline bool IsZero(AscendC::LocalTensor<T> &tensor, int64_t idx)
    {
        if constexpr (sizeof(T) == 2) {
            // For half/bfloat16, cast to float for comparison
            LocalTensor<float> castLocal = castBuf.Get<float>();
            AscendC::Cast(castLocal, tensor, AscendC::RoundMode::CAST_NONE, this->tileLength);
            float val = castLocal.GetValue(idx);
            return val == 0.0f;
        } else if constexpr (sizeof(T) == 4) {
            float val = tensor.ReinterpretCast<float>().GetValue(idx);
            return val == 0.0f;
        } else if constexpr (sizeof(T) == 8) {
            int64_t val = tensor.ReinterpretCast<int64_t>().GetValue(idx);
            return val == 0;
        }
        return true;
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueIdx;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<int64_t> outGm;
    AscendC::GlobalTensor<int64_t> stridesGm;
    AscendC::GlobalTensor<int64_t> outOffsetGm;
    int64_t blockLength;
    int64_t tileLength;
    int64_t totalLength;
    int64_t ndim;
    int64_t blockOffset;
};

extern "C" __global__ __aicore__ void nonzero(GM_ADDR x, GM_ADDR out,
                                               int64_t formerNum, int64_t formerLength,
                                               int64_t tailLength, int64_t tileLength,
                                               int64_t totalLength, int64_t ndim,
                                               GM_ADDR strides, GM_ADDR outOffset,
                                               int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelNonzero<half> op;
        op.Init(x, out, formerNum, formerLength, tailLength, tileLength,
                totalLength, ndim, strides, outOffset);
        op.Process();
    } else if (dtypeSize == 4) {
        KernelNonzero<float> op;
        op.Init(x, out, formerNum, formerLength, tailLength, tileLength,
                totalLength, ndim, strides, outOffset);
        op.Process();
    } else if (dtypeSize == 8) {
        KernelNonzero<int64_t> op;
        op.Init(x, out, formerNum, formerLength, tailLength, tileLength,
                totalLength, ndim, strides, outOffset);
        op.Process();
    }
}
