    }

    __aicore__ inline int64_t CountNonZero(int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        int64_t count = 0;

        for (int64_t k = 0; k < curTileLength; ++k) {
            if (!IsZero(xLocal, k)) {
                count++;
            }
        }

        inQueueX.FreeTensor(xLocal);
        return count;
    }

    __aicore__ inline int64_t WriteIndices(int64_t progress, int64_t curTileLength, int64_t baseOffset)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        int64_t offset = this->blockOffset + progress * this->tileLength;
        int64_t written = 0;

        for (int64_t k = 0; k < curTileLength; ++k) {
            int64_t globalIdx = offset + k;
            if (!IsZero(xLocal, k)) {
                int64_t outRow = baseOffset + written;

                // Compute multi-dimensional indices from flat index
                int64_t remain = globalIdx;
                for (int64_t d = 0; d < this->ndim; ++d) {
                    int64_t stride = stridesGm.GetValue(d);
                    int64_t idx = remain / stride;
                    remain = remain % stride;

                    int64_t outPos = outRow * this->ndim + d;
                    outGm.SetValue(outPos, idx);
                }
                written++;
            }
        }

        inQueueX.FreeTensor(xLocal);
        return written;
    }

    __aicore__ inline bool IsZero(AscendC::LocalTensor<T> &tensor, int64_t idx)
    {
        if constexpr (sizeof(T) == 2) {
            half val = tensor.GetValue(idx);
            uint16_t bits = *reinterpret_cast<uint16_t*>(&val);
            return bits == 0;
        } else if constexpr (sizeof(T) == 4) {
            float val = tensor.ReinterpretCast<float>().GetValue(idx);
            return val == 0.0f;
        } else if constexpr (sizeof(T) == 8) {
            int64_t val = tensor.ReinterpretCast<int64_t>().GetValue(idx);
            return val == 0;
        }
        return true;
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<int64_t> outGm;
    AscendC::GlobalTensor<int64_t> stridesGm;
    AscendC::GlobalTensor<int64_t> outOffsetGm;
    int64_t blockLength;
    int64_t tileLength;
    int64_t totalLength;
    int64_t ndim;
    int64_t blockOffset;
};

