#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_nonzero.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor nonzero(const at::Tensor &self, int64_t as_tuple)
{
    // ---- 输入校验 ----
    TORCH_CHECK(self.is_contiguous(), "nonzero: input must be contiguous");

    int64_t totalLength = self.numel();
    int64_t ndim = self.dim();

    if (totalLength == 0) {
        if (as_tuple) {
            // Return tuple of empty 1D tensors
            // This is handled in Python wrapper
            return at::empty({0, ndim}, at::TensorOptions().dtype(at::kLong).device(self.device()));
        }
        return at::empty({0, ndim}, at::TensorOptions().dtype(at::kLong).device(self.device()));
    }

    int64_t dtypeSize = self.element_size();

    // ---- Compute strides for multi-dimensional index conversion ----
    auto shape = self.sizes();
    std::vector<int64_t> strides(ndim);
    int64_t stride = 1;
    for (int64_t i = ndim - 1; i >= 0; --i) {
        strides[i] = stride;
        stride *= shape[i];
    }

    // ---- First pass: count non-zero elements on CPU to determine output size ----
    // For simplicity and correctness, use CPU to count
    auto selfCpu = self.to(at::kCPU);
    int64_t nonzeroCount = 0;

    if (self.scalar_type() == at::kFloat) {
        const float* data = selfCpu.data_ptr<float>();
        for (int64_t i = 0; i < totalLength; ++i) {
            if (data[i] != 0.0f) nonzeroCount++;
        }
    } else if (self.scalar_type() == at::kHalf) {
        const at::Half* data = selfCpu.data_ptr<at::Half>();
        for (int64_t i = 0; i < totalLength; ++i) {
            if (float(data[i]) != 0.0f) nonzeroCount++;
        }
    } else if (self.scalar_type() == at::kBFloat16) {
        const at::BFloat16* data = selfCpu.data_ptr<at::BFloat16>();
        for (int64_t i = 0; i < totalLength; ++i) {
            if (float(data[i]) != 0.0f) nonzeroCount++;
        }
    } else if (self.scalar_type() == at::kInt) {
        const int32_t* data = selfCpu.data_ptr<int32_t>();
        for (int64_t i = 0; i < totalLength; ++i) {
            if (data[i] != 0) nonzeroCount++;
        }
    } else if (self.scalar_type() == at::kLong) {
        const int64_t* data = selfCpu.data_ptr<int64_t>();
        for (int64_t i = 0; i < totalLength; ++i) {
            if (data[i] != 0) nonzeroCount++;
        }
    } else {
        TORCH_CHECK(false, "nonzero: unsupported dtype ", self.scalar_type());
    }

    // Create output tensor
    auto output = at::empty({nonzeroCount, ndim},
                            at::TensorOptions().dtype(at::kLong).device(self.device()));

    if (nonzeroCount == 0) {
        return output;
    }

    // ---- Get hardware params ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block level tiling ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB level tiling ----
    int64_t bufferCoefficient = dtypeSize * 2 + 8;  // inQueue * 2 + strides/outOffset
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements == 0) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < alignElements) { tileLength = alignElements; }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- Create strides tensor on device ----
    auto stridesTensor = at::from_blob(
        strides.data(), {ndim},
        at::TensorOptions().dtype(at::kLong).device(at::kCPU)
    ).to(self.device());

    // ---- Create outOffset tensor (initialized to 0) ----
    auto outOffsetTensor = at::zeros({1}, at::TensorOptions().dtype(at::kLong).device(self.device()));

    // ---- Launch kernel ----
    // All parameters must be left values
    int64_t totalLengthL = totalLength;
    int64_t ndimL = ndim;
    int64_t dtypeSizeL = dtypeSize;

    EXEC_KERNEL_CMD(nonzero, blockDim,
                    self, output,
                    formerNum, formerLength, tailLength, tileLength,
                    totalLengthL, ndimL,
                    stridesTensor, outOffsetTensor,
                    dtypeSizeL);

    return output;
}

}  // namespace ascend_kernel
