from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "nonzero_ext*")

# Priority: whl import (auto TORCH_LIBRARY registration)
try:
    import nonzero_ext  # noqa: F401
except ImportError:
    # Fallback: direct .so loading
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor, as_tuple: bool = False):
        # Call the registered AscendC operator
        result = torch.ops.npu.nonzero(x, int(as_tuple))

        if as_tuple:
            # Convert 2D indices to tuple of 1D tensors
            ndim = x.dim()
            tuple_result = []
            for d in range(ndim):
                tuple_result.append(result[:, d])
            return tuple(tuple_result)

        return result
