19	at::Tensor nonzero(const at::Tensor &self, int64_t as_tuple)
20	{
21	    // ---- Input validation ----
22	    TORCH_CHECK(self.is_contiguous(), "nonzero: input must be contiguous");
23	
24	    int64_t totalLength = self.numel();
25	    int64_t ndim = self.dim();
26	
27	    if (totalLength == 0) {
28	        return at::empty({0, ndim}, at::TensorOptions().dtype(at::kLong).device(self.device()));
29	    }
30	
31	    int64_t dtypeSize = self.element_size();
32	
33	    // ---- Compute strides for multi-dimensional index conversion ----
34	    auto shape = self.sizes();
35	    std::vector<int64_t> strides(ndim);
36	    int64_t stride = 1;
37	    for (int64_t i = ndim - 1; i >= 0; --i) {
38	        strides[i] = stride;
39	        stride *= shape[i];
40	    }
41	
42	    // ---- First pass: count non-zero elements per core on CPU ----
43	    auto selfCpu = self.to(at::kCPU);
44	    std::vector<int64_t> coreCounts;
45	    int64_t nonzeroCount = 0;
46	
47	    // Get hardware params for tiling
48	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
49	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
50	
51	    // Block level tiling
52	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
53	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
54	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
55	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
56	    int64_t formerNum = usedCoreNum - 1;
57	    int64_t formerLength = totalLengthCoreAlign;
58	    int64_t tailLength = totalLength - formerNum * formerLength;
59	
60	    // Count non-zero per core
61	    coreCounts.resize(usedCoreNum, 0);
62	    if (self.scalar_type() == at::kFloat) {
63	        const float* data = selfCpu.data_ptr<float>();
64	        for (int64_t c = 0; c < usedCoreNum; ++c) {
65	            int64_t start = (c < formerNum) ? c * formerLength : formerNum * formerLength + (c - formerNum) * tailLength;
66	            int64_t len = (c < formerNum) ? formerLength : tailLength;
67	            int64_t count = 0;
68	            for (int64_t i = 0; i < len && (start + i) < totalLength; ++i) {
69	                if (data[start + i] != 0.0f) count++;
70	            }
71	            coreCounts[c] = count;
72	        }
73	    } else if (self.scalar_type() == at::kHalf) {
74	        const at::Half* data = selfCpu.data_ptr<at::Half>();
75	        for (int64_t c = 0; c < usedCoreNum; ++c) {
76	            int64_t start = (c < formerNum) ? c * formerLength : formerNum * formerLength + (c - formerNum) * tailLength;
77	            int64_t len = (c < formerNum) ? formerLength : tailLength;
78	            int64_t count = 0;
79	            for (int64_t i = 0; i < len && (start + i) < totalLength; ++i) {
80	                if (float(data[start + i]) != 0.0f) count++;
81	            }
82	            coreCounts[c] = count;
83	        }
84	    } else if (self.scalar_type() == at::kBFloat16) {
85	        const at::BFloat16* data = selfCpu.data_ptr<at::BFloat16>();
86	        for (int64_t c = 0; c < usedCoreNum; ++c) {
87	            int64_t start = (c < formerNum) ? c * formerLength : formerNum * formerLength + (c - formerNum) * tailLength;
88	            int64_t len = (c < formerNum) ? formerLength : tailLength;
89	            int64_t count = 0;
90	            for (int64_t i = 0; i < len && (start + i) < totalLength; ++i) {
91	                if (float(data[start + i]) != 0.0f) count++;
92	            }
93	            coreCounts[c] = count;
94	        }
95	    } else if (self.scalar_type() == at::kInt) {
96	        const int32_t* data = selfCpu.data_ptr<int32_t>();
97	        for (int64_t c = 0; c < usedCoreNum; ++c) {
98	            int64_t start = (c < formerNum) ? c * formerLength : formerNum * formerLength + (c - formerNum) * tailLength;
99	            int64_t len = (c < formerNum) ? formerLength : tailLength;
100	            int64_t count = 0;
101	            for (int64_t i = 0; i < len && (start + i) < totalLength; ++i) {
102	                if (data[start + i] != 0) count++;
103	            }
104	            coreCounts[c] = count;
105	        }
106	    } else if (self.scalar_type() == at::kLong) {
107	        const int64_t* data = selfCpu.data_ptr<int64_t>();
108	        for (int64_t c = 0; c < usedCoreNum; ++c) {
109	            int64_t start = (c < formerNum) ? c * formerLength : formerNum * formerLength + (c - formerNum) * tailLength;
110	            int64_t len = (c < formerNum) ? formerLength : tailLength;
111	            int64_t count = 0;
112	            for (int64_t i = 0; i < len && (start + i) < totalLength; ++i) {
113	                if (data[start + i] != 0) count++;
114	            }
115	            coreCounts[c] = count;
116	        }
117	    } else {
118	        TORCH_CHECK(false, "nonzero: unsupported dtype ", self.scalar_type());
119	    }
120	
121	    // Compute prefix sum for output offsets
122	    std::vector<int64_t> coreOffsets(usedCoreNum, 0);
123	    for (int64_t c = 1; c < usedCoreNum; ++c) {
124	        coreOffsets[c] = coreOffsets[c - 1] + coreCounts[c - 1];
125	    }
126	    nonzeroCount = coreOffsets[usedCoreNum - 1] + coreCounts[usedCoreNum - 1];
127	
128	    // Create output tensor
129	    auto output = at::empty({nonzeroCount, ndim},
130	                            at::TensorOptions().dtype(at::kLong).device(self.device()));
131	
132	    if (nonzeroCount == 0) {
133	        return output;
134	    }
135	
136	    // ---- Get hardware params ----
137	    uint64_t ubSize;
138	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
139	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
140	
141	    // ---- UB level tiling ----
142	    int64_t bufferCoefficient = dtypeSize * 2 + 8;
143	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
144	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
145	    if (dtypeSize == 0) { dtypeSize = 1; }
146	    int64_t alignElements = 32 / dtypeSize;
147	    if (alignElements == 0) { alignElements = 1; }
148	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
149	    if (tileLength < alignElements) { tileLength = alignElements; }
150	
151	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
152	
153	    // ---- Create strides tensor on device ----
154	    auto stridesCpu = at::from_blob(
155	        strides.data(), {ndim},
156	        at::TensorOptions().dtype(at::kLong).device(at::kCPU)
157	    );
158	    auto stridesTensor = stridesCpu.to(self.device());
159	
160	    // ---- Create core offsets tensor on device ----
161	    auto offsetsCpu = at::from_blob(
162	        coreOffsets.data(), {usedCoreNum},
163	        at::TensorOptions().dtype(at::kLong).device(at::kCPU)
164	    );
165	    auto offsetsTensor = offsetsCpu.to(self.device());
166	
167	    // ---- Launch kernel ----
168	    int64_t totalLengthL = totalLength;
169	    int64_t ndimL = ndim;
170	    int64_t dtypeSizeL = dtypeSize;
171	
172	    EXEC_KERNEL_CMD(nonzero, blockDim,
173	                    self, output,
174	                    formerNum, formerLength, tailLength, tileLength,
175	                    totalLengthL, ndimL,
176	                    stridesTensor, offsetsTensor,
177	                    dtypeSizeL);
178	
179	    return output;
180	}
